diff --git a/sistema/sistema.cpp b/sistema/sistema.cpp
index 59d0e91..0d3710b 100644
--- a/sistema/sistema.cpp
+++ b/sistema/sistema.cpp
@@ -829,6 +829,28 @@ bool crea_cow_condivisa()
 {
 /// @todo creare la prima copia della zona cow
 // ( SOLUZIONE 2023-06-07
+	cow_root = alloca_tab();
+	if (!cow_root)
+		return false;
+	// creiamo la zona cow con pagine in sola lettura (senza BIT_RW)
+	// e accessibili da utente (con BIT_US)
+	// la zona ha dimensione DIM_USR_COW e parte da ini_utn_w
+	vaddr end = ini_utn_w + DIM_USR_COW;
+	vaddr v = map(cow_root, ini_utn_w, end, BIT_US,
+		[](vaddr) {
+			paddr f = alloca_frame();
+			if (f)
+				memset(voidptr_cast(f), 0, DIM_PAGINA);
+			return f;
+		});
+	if (v != end) {
+		unmap(cow_root, ini_utn_w, v,
+			[](vaddr, paddr p, int) { rilascia_frame(p); });
+		rilascia_tab(cow_root);
+		cow_root = 0;
+		return false;
+	}
+	return true;
 //   SOLUZIONE 2023-06-07 )
 }

@@ -849,6 +871,46 @@ void copia_cow_condivisa(paddr dest)
 bool aggiorna_cow_privata(vaddr v)
 {
 // ( SOLUZIONE 2023-06-07
+	// controlliamo che v cada nella zona cow
+	if (v < ini_utn_w || v >= fin_utn_w)
+		return false;
+
+	// troviamo l'entrata nella tabella di livello 1 che contiene v
+	tab_iter it(esecuzione->cr3, v, 1);
+	if (!it)
+		return false;
+
+	// scendiamo fino al livello 1 (pagina)
+	while (it.get_l() > 1) {
+		if (!it.down())
+			return false;
+	}
+
+	tab_entry& e = it.get_e();
+
+	// controlliamo che l'entrata esista e sia in sola lettura
+	if (!(e & BIT_P) || (e & BIT_RW))
+		return false;
+
+	// otteniamo l'indirizzo fisico della pagina condivisa
+	paddr src = extr_IND_FISICO(e);
+
+	// allochiamo una nuova pagina
+	paddr dst = alloca_frame();
+	if (!dst)
+		return false;
+
+	// copiamo il contenuto dalla pagina condivisa a quella privata
+	memcpy(voidptr_cast(dst), voidptr_cast(src), DIM_PAGINA);
+
+	// aggiorniamo l'entrata con la nuova pagina, abilitando la scrittura
+	set_IND_FISICO(e, dst);
+	e |= BIT_RW;
+
+	// invalidiamo la traduzione nel TLB
+	invalida_entrata_TLB(v);
+
+	return true;
 //   SOLUZIONE 2023-06-07 )
 }

